// A value JSON cannot render (circular, BigInt) falls back to String, so describing a rejection never masks it.
function readableMessage(value: unknown): string {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    return String(value);
  }
}
"""
